(() => {
  const AIR = new Set(['air','cave_air','void_air'])
  const leg = {}
  const layers = []
  for (let y = 80; y >= 70; y--) {
    const rows = []
    for (let z = 566; z <= 572; z++) {
      let row = ''
      for (let x = 1134; x <= 1144; x++) {
        const b = bot.blockAt(new w.Vec3(x, y, z))
        let ch
        if (b === null) ch = '?'
        else if (AIR.has(b.name)) ch = '.'
        else {
          if (!(b.name in leg)) leg[b.name] = String.fromCharCode(65 + Object.keys(leg).length)
          ch = leg[b.name]
        }
        row += ch
      }
      rows.push(row)
    }
    layers.push('y=' + y + ' (rows z566->572, cols x1134->1144)\n' + rows.join('\n'))
  }
  return { pos: bot.entity.position.floored().toArray(), inv: w.inv(), legend: leg, map: layers.join('\n\n') }
})()
